module.exports = {
  name: 'provino-custom',
  viteEnvironment: 'ssr',
  setup(global, options) {
    global.__customOptions = JSON.stringify(options)
    global.__customSetups = (global.__customSetups ?? 0) + 1
    return {
      teardown(global) {
        delete global.__customOptions
        delete global.__customSetups
      },
    }
  },
}
